// ------------------------------------------------------------------ break cracks (10 stages, alpha overlay)
const CRACK_ORDER = (() => {
  const r = new RNG(777), seen = new Set(), order = [];
  for (let w = 0; w < 7; w++) {
    let x = 7.5 + r.range(-1, 1), y = 7.5 + r.range(-1, 1), dir = r.range(0, Math.PI * 2);
    for (let step = 0; step < 14; step++) {
      x += Math.cos(dir); y += Math.sin(dir); dir += r.range(-0.8, 0.8);
      const px = Math.round(x), py = Math.round(y);
      if (px < 0 || py < 0 || px > 15 || py > 15 || seen.has(py * 16 + px)) continue;
      seen.add(py * 16 + px);
      order.push({ x: px, y: py, s: step + w * 0.2 });
    }
  }
  return order.sort((a, b) => a.s - b.s);
})();
for (let i = 0; i < 10; i++) {
  D('crack_' + i, (t) => {
    const n = Math.max(2, Math.floor((CRACK_ORDER.length * (i + 1)) / 10));
    for (let k = 0; k < n; k++) {
      const p = CRACK_ORDER[k];
      t.set(p.x, p.y, [0, 0, 0], 200);
      if (i >= 6 && k < n / 2) { t.set(p.x + 1, p.y, [0, 0, 0], 120); t.set(p.x, p.y + 1, [0, 0, 0], 120); }
    }
  });
}

