const HANDLE = { m: hex(0x8b6a3a), l: hex(0xa9894f), d: hex(0x5f4626) };
const MATS = {
  wooden: { m: hex(0x9c7a45), l: hex(0xb89560), d: hex(0x6e5230) },
  stone: { m: hex(0x8a8a8a), l: hex(0xb0b0b0), d: hex(0x646464) },
  iron: { m: hex(0xd4d4d4), l: hex(0xf4f4f4), d: hex(0x9a9a9a) },
  golden: { m: hex(0xf8d83a), l: hex(0xfff07a), d: hex(0xc89a20) },
  diamond: { m: hex(0x4fe0d2), l: hex(0xb4fff5), d: hex(0x1f9f95) },
};
function toolSprite(t, kind, M) {
  const head = (x, y, s) => t.set(x, y, s < 0 ? M.l : s > 0 ? M.d : M.m);
  const handle = () => { for (let x = 1; x <= 10; x++) t.set(x, 15 - x, x % 2 ? HANDLE.m : HANDLE.l); t.set(1, 14, HANDLE.d); };
  if (kind === 'sword') {
    for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
      const o = x + y + 1 - 16, u = x - y;
      if (u >= -5 && o >= -1 && o <= 1 && !(u > 11 && o === 1) && !(u > 12 && o === 0)) head(x, y, o);
      else if ((u === -7 || u === -6) && x + y >= 12 && x + y <= 18) t.set(x, y, u === -7 ? HANDLE.l : HANDLE.m);
      else if (o === 0 && u >= -13 && u <= -8) t.set(x, y, u % 2 ? HANDLE.m : HANDLE.d);
    }
  } else {
    handle();
    if (kind === 'pickaxe') {
      const cx = 3.5, cy = 12.5;
      for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
        const dx = x + 0.5 - cx, dy = y + 0.5 - cy, d = Math.hypot(dx, dy), ang = Math.atan2(-dy, dx);
        if (ang < 0.03 || ang > Math.PI / 2 - 0.03) continue;
        const w = Math.sin((ang / (Math.PI / 2)) * Math.PI);
        const inner = 9.9 - (2.9 * (0.3 + 0.7 * w));
        if (d <= 9.9 && d >= inner) head(x, y, (9.9 - d) / (9.9 - inner) > 0.6 ? 1 : (9.9 - d) / (9.9 - inner) < 0.3 ? -1 : 0);
      }
    } else if (kind === 'axe') {
      const pts = [[6, 4], [10, 1], [14, 2], [14, 7], [11, 9], [9, 8]];
      for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) if (inside(x + 0.5, y + 0.5, pts)) head(x, y, x + y < 10 ? -1 : x + y > 14 ? 1 : 0);
    } else if (kind === 'shovel') {
      const cx = 11.4, cy = 4.6, ca = Math.SQRT1_2;
      for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
        const dx = x + 0.5 - cx, dy = y + 0.5 - cy;
        const al = (dx * ca - dy * ca), ac = (dx * ca + dy * ca);
        if ((al * al) / (3.8 * 3.8) + (ac * ac) / (2.7 * 2.7) <= 1) head(x, y, ac < -0.9 ? -1 : ac > 0.9 ? 1 : 0);
      }
    }
  }
  outline(t, mul(M.d, 0.42));
}
for (const mat of Object.keys(MATS)) for (const kind of ['pickaxe', 'axe', 'shovel', 'sword']) {
  D(ITEM_PREFIX + mat + '_' + kind, (t) => toolSprite(t, kind, MATS[mat]));
}
