// ------------------------------------------------------------------ public API
let cache = null;

/** Generate all textures once. Returns { names[], index{name->layer}, pixels(Uint8Array n*1024), count }. */
export function generateTextures() {
  if (cache) return cache;
  const names = [], index = {};
  const pixels = new Uint8Array(defs.length * TS * TS * 4);
  defs.forEach((d, i) => {
    const t = new Tile();
    d.fn(t, new RNG(strHash(d.name) ^ 0x9e3779b9), d.name);
    pixels.set(t.d, i * TS * TS * 4);
    names.push(d.name);
    index[d.name] = i;
  });
  if (defs.length > 256) throw new Error('Too many texture layers for the WebGL2 guaranteed minimum (256): ' + defs.length);
  cache = { names, index, pixels, count: defs.length };
  return cache;
}

/** Pixel data (1024 bytes, RGBA) of one texture by name. */
export function tilePixels(name) {
  const c = generateTextures();
  const i = c.index[name];
  if (i === undefined) throw new Error('unknown texture ' + name);
  return c.pixels.subarray(i * 1024, (i + 1) * 1024);
}
